namespace sv_f81deed6c3ae4c1cb7ad4bc4eaa6ff2e.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In per-page interactivity, all interactive components within a single
/// circuit (including interactive islands in the static layout) share the
/// same scoped instance, so changes propagate to every subscriber.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@* Interactive island embedded in the static MainLayout.
   Because it runs in the same circuit as page-level interactive
   components, it shares the same scoped ThemeService instance. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _                => "❓"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= OnThemeChanged;
    }
}

@* Reusable interactive toggle that can be dropped into any page or layout. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @ThemeSvc.AccentColor; color: @ThemeSvc.AccentColor;"
        title="Toggle theme">
    @GetThemeIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += OnThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _                => ThemeMode.Light
        };
    }

    private string GetThemeIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _                => "❓"
    };

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= OnThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px; border-color: @ThemeSvc.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var isActive = ThemeSvc.Theme == mode;
                <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        style="@(isActive ? $"background-color:{ThemeSvc.AccentColor};border-color:{ThemeSvc.AccentColor};" : "")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnAccentChanged"
                   title="Choose accent color" />
            <span style="color: @ThemeSvc.AccentColor; font-weight: bold;">
                @ThemeSvc.AccentColor
            </span>
        </div>

        <p class="text-muted small mb-0">
            Changes apply instantly across all components in this session.
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += OnThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= OnThemeChanged;
    }
}

